          "code": "import numpy as np\n\nrng = np.random.default_rng(311)\nn = 4000\n\n# -----------------------------------------------------------------------------\n# First-Principles NumPy: Structural Causal Model (SCM) dengan 3 Struktur DAG\n#   Z (Confounder: niat beli awal)      : Z -> T dan Z -> Y\n#   M (Mediator: jumlah item keranjang) : T -> M -> Y\n#   Efek langsung T -> Y (+1.50) + efek mediasi (0.80 * 1.25 = +1.00) -> Total = +2.50\n#   C (Collider pasca-perlakuan: skor interaksi/tiket CS) : T -> C <- Y\n# -----------------------------------------------------------------------------\nZ = rng.normal(0.0, 1.0, size=n)\nT = 0.90 * Z + rng.normal(0.0, 1.0, size=n)\nM = 0.80 * T + 0.40 * Z + rng.normal(0.0, 0.7, size=n)\nY = 1.50 * T + 1.25 * M + 2.20 * Z + rng.normal(0.0, 1.0, size=n)\nC = 1.40 * T + 1.10 * Y + rng.normal(0.0, 0.8, size=n)\n\nTRUE_TOTAL_EFFECT = 1.50 + 0.80 * 1.25  # +2.5000\n\ndef ols_coef_t(y: np.ndarray, cols: list[np.ndarray]) -> tuple[float, float]:\n    X = np.column_stack([np.ones(len(y))] + cols)\n    beta, *_ = np.linalg.lstsq(X, y, rcond=None)\n    resid = y - X @ beta\n    s2 = float((resid @ resid) / (len(y) - X.shape[1]))\n    cov = s2 * np.linalg.inv(X.T @ X)\n    return float(beta[1]), float(np.sqrt(cov[1, 1]))\n\nspecs = [\n    (\"1. Naif: Y ~ T (Lupa Confounder Z)\", [T]),\n    (\"2. Backdoor Benar: Y ~ T + Z\", [T, Z]),\n    (\"3. Bad Control Collider: Y ~ T + Z + C\", [T, Z, C]),\n    (\"4. Bad Control Mediator: Y ~ T + Z + M\", [T, Z, M]),\n    (\"5. Kitchen-Sink Semua: Y ~ T + Z + M + C\", [T, Z, M, C]),\n]\n\nprint(f\"=== Audit DAG Structural Causal Model (N={n}, Total Efek Sejati = +{TRUE_TOTAL_EFFECT:.4f}) ===\")\nfor label, cols in specs:\n    est, se = ols_coef_t(Y, cols)\n    print(f\"{label:42s} | tau_hat = {est:+.4f} (SE={se:.4f}) | Bias = {est - TRUE_TOTAL_EFFECT:+.4f}\")\n\n# Bukti Ekstrem Berkson's Paradox: Efek Kausal Sejati T -> Y tepat 0.0000!\nT_zero = rng.normal(0.0, 1.0, size=n)\nY_zero = rng.normal(0.0, 1.0, size=n)  # 100% independen dari T_zero!\nC_berkson = 1.20 * T_zero + 1.20 * Y_zero + rng.normal(0.0, 0.5, size=n)\n\nest_clean, se_clean = ols_coef_t(Y_zero, [T_zero])\nest_bad, se_bad = ols_coef_t(Y_zero, [T_zero, C_berkson])\nprint(\"\\n=== Berkson's Paradox / Collider Bias (Efek Kausal Sejati = 0.0000) ===\")\nprint(f\"Tanpa Collider (Benar)  : tau_hat = {est_clean:+.4f} (SE={se_clean:.4f}, z={est_clean/se_clean:+.2f})\")\nprint(f\"Kontrol Collider (Salah): tau_hat = {est_bad:+.4f} (SE={se_bad:.4f}, z={est_bad/se_bad:+.2f}) <-- BIAS PALSU SIGNIFIKAN!\")",
