          "code": "import numpy as np\nfrom scipy.stats import norm\nfrom sklearn.base import clone\nfrom sklearn.ensemble import HistGradientBoostingRegressor, RandomForestRegressor\nfrom sklearn.linear_model import RidgeCV\nfrom sklearn.model_selection import KFold\n\nrng = np.random.default_rng(3122)\nn = 1600\n\n# -----------------------------------------------------------------------------\n# Scikit-Learn 1.9: Partialling-Out DML Non-Linier (HistGBDT & RandomForest)\n# Kasus: Elastisitas Harga Surge Ride-Hailing (T = log_price, Y = log_demand)\n# dengan confounder interaksi tajam antar zona CBD, jam sibuk, dan hujan!\n# -----------------------------------------------------------------------------\nzone = rng.binomial(1, 0.5, size=n).astype(float)\npeak = rng.binomial(1, 0.5, size=n).astype(float)\nrain = rng.binomial(1, 0.4, size=n).astype(float)\nx_cont = rng.normal(0.0, 1.0, size=(n, 3))\nX = np.column_stack([zone, peak, rain, x_cont])\n\n# Fungsi confounder interaksi non-linier yang mustahil ditangkap OLS linier!\nf_int = (\n    2.6 * ((zone == 1) & (peak == 1))\n    - 2.2 * ((zone == 0) & (peak == 1))\n    + 2.4 * ((rain == 1) & (zone == 1))\n    - 1.8 * ((rain == 1) & (peak == 0))\n)\ng_true = 1.9 * f_int + 1.2 * x_cont[:, 0]\nm_true = 0.85 * f_int + 0.3 * x_cont[:, 1]\ntheta_true = -1.80\n\nT = m_true + rng.normal(0.0, 0.70, size=n)\nY = theta_true * T + g_true + rng.normal(0.0, 0.85, size=n)\n\ndef run_partialling_out_dml(X_mat: np.ndarray, T_vec: np.ndarray, Y_vec: np.ndarray, model_y, model_t, n_splits: int = 5):\n    kf = KFold(n_splits=n_splits, shuffle=True, random_state=42)\n    y_hat_oof = np.empty(len(Y_vec))\n    t_hat_oof = np.empty(len(T_vec))\n    for tr_idx, val_idx in kf.split(X_mat):\n        y_hat_oof[val_idx] = clone(model_y).fit(X_mat[tr_idx], Y_vec[tr_idx]).predict(X_mat[val_idx])\n        t_hat_oof[val_idx] = clone(model_t).fit(X_mat[tr_idx], T_vec[tr_idx]).predict(X_mat[val_idx])\n\n    y_res = Y_vec - y_hat_oof\n    t_res = T_vec - t_hat_oof\n    denom = float(np.sum(t_res ** 2))\n    theta_hat = float(np.sum(t_res * y_res) / denom)\n    # Heteroskedasticity-robust Sandwich SE (Chernozhukov et al. 2018)\n    se = float(np.sqrt(np.sum((t_res * (y_res - theta_hat * t_res)) ** 2)) / denom)\n    p_val = float(2.0 * (1.0 - norm.cdf(abs(theta_hat / se))))\n    r2_y = float(1.0 - np.sum(y_res ** 2) / np.sum((Y_vec - Y_vec.mean()) ** 2))\n    r2_t = float(1.0 - np.sum(t_res ** 2) / np.sum((T_vec - T_vec.mean()) ** 2))\n    return theta_hat, se, p_val, r2_y, r2_t\n\ntheta_ols = float(np.linalg.lstsq(np.column_stack([np.ones(n), T, X]), Y, rcond=None)[0][1])\n\nmodels = [\n    (\"DML + RidgeCV (Linier Misspecified)\", RidgeCV(alphas=[0.1, 1.0, 10.0]), RidgeCV(alphas=[0.1, 1.0, 10.0])),\n    (\"DML + RandomForest (Non-Linier)    \", RandomForestRegressor(n_estimators=40, max_depth=6, min_samples_leaf=8, random_state=42), RandomForestRegressor(n_estimators=40, max_depth=6, min_samples_leaf=8, random_state=42)),\n    (\"DML + HistGBDT (Non-Linier SOTA)   \", HistGradientBoostingRegressor(max_depth=4, max_iter=55, max_bins=64, min_samples_leaf=15, random_state=42), HistGradientBoostingRegressor(max_depth=4, max_iter=55, max_bins=64, min_samples_leaf=15, random_state=42)),\n]\n\nprint(f\"=== Elastisitas Harga Surge Non-Linier (N={n}, True Elasticity theta_0 = {theta_true:+.4f}) ===\")\nprint(f\"OLS Linier Biasa (Misspecified!)    | theta_hat = {theta_ols:+.4f} | Bias = {theta_ols - theta_true:+.4f} (HANCUR!)\")\nfor name, my, mt in models:\n    th, se, pv, r2y, r2t = run_partialling_out_dml(X, T, Y, my, mt, n_splits=5)\n    ci_lo, ci_hi = th - 1.96 * se, th + 1.96 * se\n    print(f\"{name} | theta={th:+.4f} +/- {1.96*se:.4f} (CI [{ci_lo:+.3f}, {ci_hi:+.3f}]) | OOF R2(Y)={r2y:.3f}, R2(T)={r2t:.3f}\")",
          "expectedOutput": "=== Elastisitas Harga Surge Non-Linier (N=1600, True Elasticity theta_0 = -1.8000) ===\nOLS Linier Biasa (Misspecified!)    | theta_hat = -0.1253 | Bias = +1.6747 (HANCUR!)\nDML + RidgeCV (Linier Misspecified) | theta=-0.1250 +/- 0.0494 (CI [-0.174, -0.076]) | OOF R2(Y)=0.476, R2(T)=0.544\nDML + RandomForest (Non-Linier)     | theta=-1.6938 +/- 0.0710 (CI [-1.765, -1.623]) | OOF R2(Y)=0.474, R2(T)=0.883\nDML + HistGBDT (Non-Linier SOTA)    | theta=-1.6915 +/- 0.0669 (CI [-1.758, -1.625]) | OOF R2(Y)=0.489, R2(T)=0.880",
