          "code": "import numpy as np\n\nrng = np.random.default_rng(313)\nn = 4000\n\n# -----------------------------------------------------------------------------\n# First-Principles NumPy: Simulasi 4 Kuadran Pelanggan Retensi Langganan\n# Ekonomi: Margin retensi berhasil = +$60, Biaya voucher promo = -$18\n#   Kuadran 1: Persuadables  (P_retain: 0.25 -> 0.80, Uplift = +0.55) -> TARGET UTAMA!\n#   Kuadran 2: Sure Things   (P_retain: 0.92 -> 0.92, Uplift =  0.00) -> BUANG UANG!\n#   Kuadran 3: Lost Causes   (P_retain: 0.08 -> 0.10, Uplift = +0.02) -> SIA-SIA!\n#   Kuadran 4: Sleeping Dogs (P_retain: 0.82 -> 0.52, Uplift = -0.30) -> BERBAHAYA!\n# -----------------------------------------------------------------------------\nprobs_q = [0.22, 0.30, 0.28, 0.20]\nquad = rng.choice(4, size=n, p=probs_q)\n\np_retain_0 = np.array([0.25, 0.92, 0.08, 0.82])[quad]\np_retain_1 = np.array([0.80, 0.92, 0.10, 0.52])[quad]\ntrue_cate = p_retain_1 - p_retain_0\ntrue_churn_risk = 1.0 - p_retain_0\n\nscore_churn = np.clip(true_churn_risk + rng.normal(0.0, 0.08, size=n), 0.0, 1.0)\nscore_uplift = true_cate + rng.normal(0.0, 0.10, size=n)\n\nMARGIN_SAVE = 60.0\nCOST_PROMO = 18.0\nTOP_K = int(0.25 * n)  # Kuota anggaran promo: Top-25% (1.000 pelanggan)\n\ndef eval_targeting(name: str, scores: np.ndarray):\n    idx = np.argsort(-scores, kind=\"mergesort\")[:TOP_K]\n    exp_inc_ret = float(np.sum(true_cate[idx]))\n    net_profit = exp_inc_ret * MARGIN_SAVE - TOP_K * COST_PROMO\n    shares = [float(np.mean(quad[idx] == q)) for q in range(4)]\n    print(\n        f\"{name:26s} | Persuad={shares[0]:5.1%} Sure={shares[1]:4.1%} Lost={shares[2]:5.1%} Sleep={shares[3]:4.1%} \"\n        f\"| IncRet={exp_inc_ret:+6.1f} | NetProfit=${net_profit:+9,.2f}\"\n    )\n\nprint(f\"=== Komparasi Strategi Penargetan Top-25% (K={TOP_K}, Margin=$60, Promo=$18) ===\")\neval_targeting(\"1. Target Acak 25%        \", rng.uniform(0, 1, size=n))\neval_targeting(\"2. Model Prediksi Churn   \", score_churn)\neval_targeting(\"3. Model Uplift CATE      \", score_uplift)\n\nall_inc_ret = float(np.sum(true_cate))\nall_profit = all_inc_ret * MARGIN_SAVE - n * COST_PROMO\nprint(f\"\\nBlast 100% Populasi (N={n}) | IncRet={all_inc_ret:+6.1f} | NetProfit=${all_profit:+9,.2f} (RUGI BESAR!)\")",
