          "id": "code-ml-31-3-ch31_3_diag",
          "title": "Production Audit: S-Learner Regularization Collapse di p=32 & R-Learner Guardrail + Proteksi Sleeping Dogs",
          "language": "python",
          "filename": "31_3_slearner_collapse_and_rlearner_guardrail_audit.py",
          "code": "import numpy as np\nfrom sklearn.ensemble import RandomForestRegressor\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.model_selection import KFold\n\nrng = np.random.default_rng(3133)\n\n# -----------------------------------------------------------------------------\n# Audit 1: S-Learner Regularization Collapse Saat Dimensi Fitur Noise Bertambah\n# -----------------------------------------------------------------------------\nprint(\"=== 1. Audit S-Learner Regularization Collapse Saat Fitur Noise Bertambah ===\")\nn = 1200\nfor p_noise in [0, 30]:\n    X = rng.normal(0.0, 1.0, size=(n, 2 + p_noise))\n    T = rng.binomial(1, 0.15, size=n)\n    tau_true = 1.80 + 0.90 * X[:, 0]\n    Y = 2.0 * X[:, 0] + 1.5 * np.sin(X[:, 1]) + T * tau_true + rng.normal(0.0, 1.2, size=n)\n\n    s_rf = RandomForestRegressor(n_estimators=40, max_depth=6, max_features=\"sqrt\", min_samples_leaf=15, random_state=42)\n    s_rf.fit(np.column_stack([X, T]), Y)\n    tau_hat = s_rf.predict(np.column_stack([X, np.ones(n)])) - s_rf.predict(np.column_stack([X, np.zeros(n)]))\n    shrink_pct = (1.0 - float(tau_hat.mean() / tau_true.mean())) * 100.0\n    print(f\"p_total={2+p_noise:2d} | True Mean CATE={tau_true.mean():+.3f} | S-Learner Mean={tau_hat.mean():+.3f} | Shrinkage Bias={shrink_pct:5.1f}%\")\n\n# -----------------------------------------------------------------------------\n# Audit 2: R-Learner Guardrail (|T_tilde| < 0.05) & Proteksi Sleeping Dogs\n# -----------------------------------------------------------------------------\nn2 = 1200\nX2 = rng.normal(0.0, 1.0, size=(n2, 6))\ne_true = 1.0 / (1.0 + np.exp(-(2.5 * X2[:, 0])))\nT2 = rng.binomial(1, e_true)\ntau2 = 1.8 * X2[:, 1] - 0.6  # ~37% populasi adalah Sleeping Dogs (tau < 0)!\nY2 = 2.0 * X2[:, 0] + T2 * tau2 + rng.normal(0.0, 1.0, size=n2)\n\nkf = KFold(n_splits=4, shuffle=True, random_state=42)\nm_oof, e_oof = np.empty(n2), np.empty(n2)\nfor tr, va in kf.split(X2):\n    m_oof[va] = RandomForestRegressor(n_estimators=25, max_depth=5, min_samples_leaf=15, random_state=42).fit(X2[tr], Y2[tr]).predict(X2[va])\n    e_oof[va] = LogisticRegression(max_iter=300).fit(X2[tr], T2[tr]).predict_proba(X2[va])[:, 1]\n\nt_res, y_res = T2 - e_oof, Y2 - m_oof\ntiny_t = np.abs(t_res) < 0.05\nz_raw_max = float(np.max(np.abs(y_res / np.where(t_res == 0, 1e-9, t_res))))\nz_safe_max = float(np.max(np.abs(y_res[~tiny_t] / t_res[~tiny_t])))\n\nr_safe = RandomForestRegressor(n_estimators=35, max_depth=5, min_samples_leaf=15, random_state=42)\nr_safe.fit(X2[~tiny_t], y_res[~tiny_t] / t_res[~tiny_t], sample_weight=t_res[~tiny_t] ** 2)\ntau_hat2 = r_safe.predict(X2)\nsuppress_mask = tau_hat2 < 0.0\n\nprint(\"\\n=== 2. Audit R-Learner Stabilitas & Suppression List Sleeping Dogs (Do-Not-Contact) ===\")\nprint(f\"Baris |T_tilde| < 0.05: {int(tiny_t.sum())} | Max |z| Tanpa Filter={z_raw_max:.1f} vs Dengan Filter={z_safe_max:.2f}\")\nprint(f\"Segmen Terblokir (tau_hat < 0): {int(suppress_mask.sum())} user | True Mean CATE Terblokir = {tau2[suppress_mask].mean():+.4f}\")\nprint(f\"Segmen Ditarget  (tau_hat >= 0): {int((~suppress_mask).sum())} user | True Mean CATE Ditarget  = {tau2[~suppress_mask].mean():+.4f}\")",
          "expectedOutput": "=== 1. Audit S-Learner Regularization Collapse Saat Fitur Noise Bertambah ===\np_total= 2 | True Mean CATE=+1.781 | S-Learner Mean=+1.158 | Shrinkage Bias= 35.0%\np_total=32 | True Mean CATE=+1.796 | S-Learner Mean=+0.874 | Shrinkage Bias= 51.3%\n\n=== 2. Audit R-Learner Stabilitas & Suppression List Sleeping Dogs (Do-Not-Contact) ===\nBaris |T_tilde| < 0.05: 286 | Max |z| Tanpa Filter=8497.6 vs Dengan Filter=41.15\nSegmen Terblokir (tau_hat < 0): 808 user | True Mean CATE Terblokir = -1.5779\nSegmen Ditarget  (tau_hat >= 0): 392 user | True Mean CATE Ditarget  = +1.1536",
